CREATE TABLE IF NOT EXISTS correos (
    id INTEGER PRIMARY KEY,
    para TEXT NOT NULL,
    asunto TEXT NOT NULL,
    cuerpo TEXT NOT NULL,
    creado TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS espera (
    id INTEGER PRIMARY KEY,
    socio_id INTEGER NOT NULL REFERENCES socios(id),
    clase_id INTEGER NOT NULL REFERENCES clases(id),
    creada TEXT NOT NULL
);
"""

_transaccion = threading.local()


def ruta():
    return os.environ.get('PULSO_DB', 'pulso.db')


def _abrir(**kwargs):
    con = sqlite3.connect(ruta(), **kwargs)
    con.row_factory = sqlite3.Row
    con.execute('PRAGMA foreign_keys = ON')
    return con


@contextmanager
def conexion():
    """Dentro de transaccion() devuelve la conexión de esa transacción; afuera, una propia que se confirma al salir."""
    activa = getattr(_transaccion, 'con', None)
    if activa is not None:
        yield activa
        return
    con = _abrir()
    try:
        yield con
        con.commit()
    finally:
        con.close()


@contextmanager
def transaccion():
    """Todo lo que se haga adentro es una sola transacción: se confirma al salir, o se deshace si hay un error.
    BEGIN IMMEDIATE toma el lock de escritura al empezar, así dos operaciones no leen el mismo estado a la vez."""
    con = _abrir(isolation_level=None)
    con.execute('BEGIN IMMEDIATE')
    _transaccion.con = con
    try:
        yield con
    except BaseException:
        if con.in_transaction:
            con.execute('ROLLBACK')
        raise
    else:
        con.execute('COMMIT')
    finally:
        _transaccion.con = None
